// ── Production-grade fetch wrapper: timeouts, safe retries, error handling ──
const IDEMPOTENT = new Set(['GET', 'HEAD', 'PUT', 'DELETE', 'OPTIONS']);
const RETRYABLE_STATUS = new Set([408, 429, 500, 502, 503, 504]);
const sleep = ms => new Promise(r => setTimeout(r, ms));

function retryDelay(res, attempt) {
  const header = res?.headers.get('Retry-After');     // "120" or an HTTP date
  if (header) {
    const seconds = Number(header);
    const ms = Number.isNaN(seconds) ? Date.parse(header) - Date.now() : seconds * 1000;
    if (ms > 0) return Math.min(ms, 30_000);
  }
  return 2 ** attempt * 200 + Math.random() * 100;    // exponential backoff + jitter
}

function httpClient(baseUrl, defaultHeaders = {}) {
  async function request(method, path, body, { retries = 3, timeoutMs = 10_000, idempotencyKey } = {}) {
    const headers = { Accept: 'application/json', ...defaultHeaders };
    if (body !== undefined) headers['Content-Type'] = 'application/json';
    if (idempotencyKey) headers['Idempotency-Key'] = idempotencyKey;
    // Retry only when repeating the request cannot create a duplicate side effect
    const canRetry = IDEMPOTENT.has(method) || Boolean(idempotencyKey);

    for (let attempt = 1; ; attempt++) {
      let res;
      try {
        res = await fetch(`${baseUrl}${path}`, {
          method,
          headers,
          body: body === undefined ? undefined : JSON.stringify(body),
          signal: AbortSignal.timeout(timeoutMs),     // never hang forever
        });
      } catch (networkErr) {                          // DNS failure, refused, reset, timeout
        if (!canRetry || attempt >= retries) throw networkErr;
        await sleep(retryDelay(null, attempt));
        continue;
      }

      if (RETRYABLE_STATUS.has(res.status) && canRetry && attempt < retries) {
        await res.body?.cancel();                     // release the connection
        await sleep(retryDelay(res, attempt));
        continue;
      }
      if (!res.ok) {                                  // other 4xx: fix the request, don't retry
        const err = new Error(`HTTP ${res.status}: ${await res.text().catch(() => '')}`);
        err.status = res.status;
        throw err;
      }
      if (res.status === 204) return null;            // success with no body
      return res.json();
    }
  }

  return {
    get:    (path, opts)       => request('GET', path, undefined, opts),
    post:   (path, body, opts) => request('POST', path, body, opts),
    put:    (path, body, opts) => request('PUT', path, body, opts),
    patch:  (path, body, opts) => request('PATCH', path, body, opts),
    delete: (path, opts)       => request('DELETE', path, undefined, opts),
  };
}

