// ── REST URL conventions ──────────────────────────────────────
// GET    /users           → list users (paginated)
// POST   /users           → create user (returns 201 + Location)
// GET    /users/:id       → get one user (404 if not found)
// PUT    /users/:id       → replace user entirely
// PATCH  /users/:id       → partial update
// DELETE /users/:id       → delete user (returns 204)
// GET    /users/:id/posts → nested resource: posts by user

// ── WebSocket client with reconnection and heartbeat ────────────
function createReconnectingWebSocket(url, handlers = {}) {
  let ws = null;
  let reconnectDelay = 1000;
  let heartbeatTimer = null;
  let isClosed = false;

  function connect() {
    if (isClosed) return;
    ws = new WebSocket(url);

    ws.addEventListener('open', () => {
      console.log('WS connected');
      reconnectDelay = 1000; // reset backoff on successful connection
      handlers.onOpen?.();

      // Send a ping every 30 seconds to keep connection alive
      // (some load balancers close idle connections)
      heartbeatTimer = setInterval(() => {
        if (ws.readyState === WebSocket.OPEN) {
          ws.send(JSON.stringify({ type: 'ping' }));
        }
      }, 30_000);
    });

    ws.addEventListener('message', (event) => {
      const msg = JSON.parse(event.data);
      if (msg.type === 'pong') return; // ignore heartbeat responses
      handlers.onMessage?.(msg);
    });

    ws.addEventListener('close', ({ code, reason }) => {
      clearInterval(heartbeatTimer);
      console.log(`WS closed: ${code} ${reason}`);
      handlers.onClose?.(code, reason);

      // Reconnect unless WE closed it. (1001 "going away" from the server usually
      // means a deploy or restart — exactly when you want to come back.)
      if (!isClosed) {
        const jitter = Math.random() * 1000; // spread out reconnect storms
        setTimeout(connect, reconnectDelay + jitter);
        reconnectDelay = Math.min(reconnectDelay * 2, 30_000); // cap at 30s
      }
    });

    ws.addEventListener('error', (err) => {
      console.error('WS error', err);
      handlers.onError?.(err);
      // 'error' is always followed by 'close', so reconnect logic is there
    });
  }

  connect();

  return {
    send(msg) {
      if (ws?.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify(msg));
      } else {
        console.warn('WS not open, message dropped:', msg);
      }
    },
    close() {
      isClosed = true;
      clearInterval(heartbeatTimer);
      ws?.close(1000, 'Client closed');
    },
  };
}

